public class DatabaseOperationExecutor
{
    public async Task ExecuteDatabaseOperation(DbConnection dbConnection, string sqlCommand, List<object> parameters, DatabaseOperationContext context)
    {
        if (dbConnection == null || !dbConnection.State.Equals(ConnectionState.Open))
        {
            throw new InvalidOperationException("Database connection is not open.");
        }

        if (string.IsNullOrEmpty(sqlCommand))
        {
            throw new ArgumentNullException("sqlCommand");
        }

        if (parameters == null || parameters.Count == 0)
        {
            throw new ArgumentException("Parameter list cannot be empty.");
        }

        if (context == null || context.Callback == null)
        {
            throw new ArgumentNullException("DatabaseOperationContext");
        }

        try
        {
            // Exponential backoff retry logic for transient failures
            int retryCount = 0;
            while (retryCount < 3) // Example: Retry up to 3 times
            {
                try
                {
                    using (var command = new SqlCommand(sqlCommand, dbConnection))
                    {
                        command.Parameters.AddRange(parameters.Cast<SqlParameter>().ToArray());

                        // Execute the SQL command and process the result set efficiently
                        // ...

                        // Invoke the callback function with the result
                        await context.Callback(result); 
                        return; 
                    }
                }
                catch (Exception ex)
                {
                    // Log the error and implement exponential backoff
                    retryCount++;
                    Console.WriteLine($"Error during database operation: {ex.Message}. Retrying in {Math.Pow(2, retryCount)} seconds.");
                    await Task.Delay((int)Math.Pow(2, retryCount) * 1000); // Adjust delay as needed
                }
            }

            throw new Exception("Database operation failed after multiple retries.");
        }
        catch (Exception ex)
        {
            // Log the error in a structured format
            Console.WriteLine($"An unhandled exception occurred during database operation: {ex.Message}");
            // ... Implement custom error handling and logging
            throw; // Re-throw to propagate the exception
        }
    }
}


