from concurrent.futures import ThreadPoolExecutor
import websocket
import json
import time
from collections import defaultdict
from flask import Flask, jsonify

app = Flask(__name__)

status_codes = {
    200: 'Success',
    201: 'Created',
    400: 'Bad Request',
    404: 'Not Found',
}

content_types = {'json': 0, 'html': 0, 'xml': 0}  

def process_log(log_entry):
    try:
        data = json.loads(log_entry['payload'])
        status_code = data['status_code']
        content_type = data['content_type']

        if status_code in status_codes and content_type:
            content_types[content_type] += 1  
            # Calculate average response time (example)
            avg_response_time = data['response_time'] / 1000  
    except (json.JSONDecodeError, KeyError):
        print(f"Invalid log entry: {log_entry}")

def on_message(ws, message):
    try:
        log_entry = json.loads(message)
        with ThreadPoolExecutor(max_workers=10) as executor:
            executor.submit(process_log, log_entry)
    except Exception as e:
        print(f"Error processing message: {e}")

def on_error(ws, error):
    print(f"Connection error: {error}")

def on_close(ws, close_status_code, close_msg):
    print("WebSocket connection closed")

def on_open(ws):
    print("WebSocket connection opened")

if __name__ == "__main__":
    websocket.enableTrace(True)  # Enable logging for debugging
    ws = websocket.WebSocketApp(
        "ws://your-api-endpoint", 
        on_message=on_message, 
        on_error=on_error, 
        on_close=on_close, 
        on_open=on_open,
    )
    ws.run_forever()

@app.route('/metrics')
def get_metrics():
    return jsonify(content_types)


if __name__ == "__main__":
    app.run(debug=True) 
