const FooterScriptManager = (scriptArray) => {
  const renderFooter = async () => {
    const footerContainer = document.getElementById('footer'); // Assuming your footer has an ID 'footer'

    for (const scriptObj of scriptArray) {
      if (!scriptObj.key || !scriptObj.code) {
        console.warn(`Skipping script with missing key or code: ${JSON.stringify(scriptObj)}`);
        continue;
      }

      const metadataPromise = fetchMetadata(scriptObj.key); // Fetch metadata asynchronously

      try {
        const metadata = await metadataPromise; 
        const scriptElement = document.createElement('script');
        scriptElement.src = scriptObj.code;

        if (metadata) {
          // Inject metadata as data attributes for potential use later
          Object.keys(metadata).forEach(key => {
            scriptElement.setAttribute(`data-${key}`, metadata[key]); 
          });
        }

        footerContainer.appendChild(scriptElement);
      } catch (error) {
        console.error(`Error rendering script ${scriptObj.key}:`, error);
      }
    }
  };

  // ... implementation for fetchMetadata, retry logic, error handling, etc. ...

  return { renderFooter }; 
};

