const config = require('./config');

app.use(rateLimiter);

app.get('/execute', async (req, res) => {
  const moduleName = req.query.module;
  const envVar = req.headers['env-var']; // Example header for conditional loading
  const runtimeCondition = req.query.condition; // Example query parameter for runtime condition

  // Determine module to load based on input and conditions
  let loadedModule;
  if (config[moduleName] && envVar === 'production') {
    loadedModule = await loadModule(moduleName);
  } else if (runtimeCondition === 'true') {
    loadedModule = await loadModule(`${moduleName}-dynamic`);
  }

  // Execute module and handle response
  try {
    const result = await loadedModule.execute();
    res.json(result);
  } catch (error) {
    console.error(`Error executing module ${moduleName}:`, error);
    res.status(500).send('Error executing module');
  }
});

async function loadModule(name) {
  if (moduleCache.has(name)) {
    return moduleCache.get(name);
  }

  try {
    const modulePath = `./modules/${name}.js`; // Adjust path as needed
    const moduleCode = await promisify(fs.readFile)(modulePath, 'utf8');
    const loadedModule = eval(moduleCode); // Evaluate module code
    moduleCache.set(name, loadedModule);
    return loadedModule;
  } catch (error) {
    console.error(`Error loading module ${name}:`, error);
    // Implement failover strategy here
  }
}

app.listen(port, () => {
  console.log(`Microservice listening on port ${port}`);
});



