public class DisjointPairService {

    private final int CHUNK_SIZE = 100_000;
    private final UnionFind disjointSet = new UnionFind(); 
    private final ExecutorService executor = Executors.newFixedThreadPool(4); // Adjust thread pool size based on your needs
    private final DataValidationStrategy validationStrategy;

    public DisjointPairService(DataValidationStrategy validationStrategy) {
        this.validationStrategy = validationStrategy;
    }

    public void processDataset(List<Integer> dataset) throws InterruptedException {
        long startTime = System.currentTimeMillis();

        // Chunked Processing
        int numChunks = (int) Math.ceil((double) dataset.size() / CHUNK_SIZE);
        for (int i = 0; i < numChunks; i++) {
            List<Integer> chunk = dataset.subList(i * CHUNK_SIZE, Math.min((i + 1) * CHUNK_SIZE, dataset.size()));
            executor.execute(() -> processChunk(chunk)); 
        }

        // Wait for all chunks to finish processing
        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.HOURS);

        long endTime = System.currentTimeMillis();
        System.out.println("Total Processing Time: " + (endTime - startTime) + "ms");
    }

    private void processChunk(List<Integer> chunk) {
        for (int num : chunk) {
            if (validationStrategy.isValid(num)) { // External validation check
                disjointSet.union(num); 
            } else {
                // Log error asynchronously
                handleValidationError(num); 
            }
        }

    }

    // ... Implementation for handleValidationError, external integration, etc. ...
}


