impl HttpClient {
    fn new(base_url: &str, auth_service: AuthService) -> Self {
        let pool = reqwest::blocking::ClientBuilder::new()
            .pool(reqwest::blocking::Pool::builder().build()); 

        Self { pool, auth_service }
    }

    async fn get(&self, path: &str) -> Result<reqwest::blocking::Response, Error> {
        let token = self.auth_service.get_token().await?;

        let req = self.pool.build().get(format!("{}/{}", base_url, path))
            .header("Authorization", format!("Bearer {}", token)); 

        req.send().await.map_err(|e| Error::HttpError(e)) 
    }

    // ... (Other HTTP methods like post, put, delete)
}

#[derive(Debug)]
enum Error {
    HttpError(reqwest::blocking::Error), // Custom error for HTTP errors
    AuthenticationError(String),  // For auth-related issues
    // ... other potential error types
}

