namespace RandomValueGenerator
{
    public class RandomValueGeneratorConfig
    {
        public int Min { get; set; }
        public int Max { get; set; }
        public List<int> ValidIntegers { get; set; } = new List<int>();
    }

    public class RandomValueGenerator
    {
        private readonly RandomValueGeneratorConfig _config;
        private readonly IRandomNumberGenerator _randomNumberGenerator;
        private static readonly object _lockObject = new object();
        private bool _initialized = false;

        public RandomValueGenerator(IRandomNumberGenerator randomNumberGenerator, string configPath)
        {
            _randomNumberGenerator = randomNumberGenerator ?? throw new ArgumentNullException(nameof(randomNumberGenerator));
            LoadConfig(configPath);
        }

        private void LoadConfig(string configPath)
        {
            if (!File.Exists(configPath))
            {
                throw new FileNotFoundException($"Configuration file not found at '{configPath}'");
            }
            string configJson = File.ReadAllText(configPath);
            _config = JsonSerializer.Deserialize<RandomValueGeneratorConfig>(configJson);
        }

        public int GenerateInteger()
        {
            lock (_lockObject)
            {
                if (!_initialized)
                {
                    Initialize();
                }
                return _randomNumberGenerator.GenerateInt(_config.Min, _config.Max, _config.ValidIntegers);
            }
        }

        public float GenerateFloat()
        {
            lock (_lockObject)
            {
                if (!_initialized)
                {
                    Initialize();
                }
                return _randomNumberGenerator.GenerateFloat(_config.Min, _config.Max);
            }
        }

        private void Initialize()
        {
            _initialized = true;
            // Perform any necessary initialization here
        }
    }

    public interface IRandomNumberGenerator
    {
        int GenerateInt(int min, int max, List<int> validIntegers);
        float GenerateFloat(int min, int max);
    }
}
