typedef struct {
    int* numbers;
    int size;
} ReductionJob;

void* reduceNumbers(void* jobData) {
    ReductionJob* job = (ReductionJob*)jobData;
    int sum = 0;
    for (int i = 0; i < job->size; ++i) {
        sum += job->numbers[i];
    }
    pthread_exit((void*)sum);
}

int processResourceBundleAsync(const char* filePath, int* numbers, int numNumbers) {
    // Fetch resource bundle data asynchronously 
    ResourceBundleResult result = fetchResourceBundle(filePath);
    if (result.error_code != 0) {
        fprintf(stderr, "Error fetching resource bundle: %s\n", result.data);
        return -1; // Handle API error
    }

    // Create reduction jobs for processing the numbers array in parallel
    pthread_t threads[4];  // Adjust number of threads based on system capabilities
    ReductionJob jobs[4] = {
        {numbers, numNumbers / 4},
        {numbers + (numNumbers / 4), numNumbers / 4},
        {numbers + (2 * (numNumbers / 4)), numNumbers / 4},
        {numbers + (3 * (numNumbers / 4)), numNumbers / 4}
    };

    for (int i = 0; i < 4; ++i) {
        pthread_create(&threads[i], NULL, reduceNumbers, &jobs[i]);
    }

    // Wait for threads to complete
    int sums[4];
    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], (void**)&sums[i]);
    }

    // Combine the partial sums from each thread
    int totalSum = sums[0] + sums[1] + sums[2] + sums[3];

    return totalSum;
}



