class ResourceLoader:

    def __init__(self, config_dir):
        self.config_dir = config_dir
        self.plugins = {}
        self.cache = {}  
        self._load_plugins()

    def _load_plugins(self):
        for plugin_file in os.listdir(self.config_dir):
            if plugin_file.endswith(".py"):
                try:
                    plugin_module = importlib.import_module(f"plugins.{plugin_file[:-3]}")
                    plugin_class = getattr(plugin_module, "ResourcePlugin")
                    plugin_instance = plugin_class()
                    self.plugins[plugin_instance.format] = plugin_instance

                except Exception as e:
                    logger.warning(f"Failed to load plugin {plugin_file}: {e}")

    def load_resource(self, resource_path, format):
        if format not in self.plugins:
            raise ValueError(f"Unsupported format: {format}")

        return self.plugins[format].load_from_file(resource_path)


# Example usage 
