typedef struct {
    OAuth2Response *response;
    ValidationResult *result;
} ValidationContext;

void *validate_token(void *context) {
    ValidationContext *ctx = (ValidationContext *) context;
    OAuth2Response *response = ctx->response;

    // Token type verification
    if (strcmp(response->token_type, "Bearer") != 0) {
        *ctx->result = TOKEN_TYPE_MISMATCH;
        return NULL;
    }

    // Expiration time validation
    if (response->expires_in <= 0) {
        *ctx->result = EXPIRES_IN_INVALID;
        return NULL;
    }

