from flask import Flask, request, jsonify
import threading
from redis import Redis

app = Flask(__name__)
redis_client = Redis(host='localhost', port=6379, db=0)

def fetch_data(api_url):
    try:
        response = requests.get(api_url)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"Error fetching data from {api_url}: {e}")
        return None

def update_cache(api_url):
    data = fetch_data(api_url)
    if data:
        redis_client.set(api_url, json.dumps(data))

@app.route('/api/<api_key>', methods=['GET'])
def get_data(api_key):
    cached_data = redis_client.get(api_key)
    if cached_data:
        return jsonify(json.loads(cached_data))
    else:
        threading.Thread(target=update_cache, args=(api_key,)).start()
        return "Data is being updated, please try again later"

if __name__ == '__main__':
