typedef struct {
    sem_t *semaphores;
    int size;
    int currentSize;
    int initialValue; 
} SemaphorePool;

SemaphorePool* createSemaphorePool(int size, int initialValue) {
    SemaphorePool* pool = (SemaphorePool*) malloc(sizeof(SemaphorePool));
    pool->semaphores = (sem_t*) malloc(size * sizeof(sem_t));
    pool->size = size;
    pool->currentSize = 0;
    pool->initialValue = initialValue;

    for (int i = 0; i < size; i++) {
        if (sem_init(&pool->semaphores[i], 0, initialValue) == -1) {
            // Handle semaphore creation failure
            fprintf(stderr, "Error initializing semaphore\n");
            free(pool->semaphores);
            free(pool);
            return NULL;
        }
    }

    return pool;
}


void acquireSemaphore(SemaphorePool* pool) {
    // Implement priority-based acquisition logic here. 
    for (int i = 0; i < pool->currentSize; i++) {
        if (sem_wait(&pool->semaphores[i]) == 0) {
            return; // Acquired semaphore
        }
    }

    // Handle timeout or fallback strategy
}


void releaseSemaphore(SemaphorePool* pool) {
    // Implement logic for releasing semaphores.
}

