public async Task ExecuteDatabaseOperation(DbConnection dbConnection, string sqlCommand, List<object> parameters, DatabaseOperationContext context)
{
    if (dbConnection == null || !dbConnection.State.Equals(ConnectionState.Open))
    {
        Logger.LogError("Database connection invalid: {0}", dbConnection);
        return;
    }

    if (string.IsNullOrEmpty(sqlCommand))
    {
        Logger.LogError("SQL command is empty.");
        return;
    }

    if (parameters == null || parameters.Count == 0)
    {
        Logger.LogError("Parameter list is empty.");
        return;
    }

    if (context == null || context.Callback == null)
    {
        Logger.LogError("Missing callback function in DatabaseOperationContext.");
        return;
    }

    int retryCount = 0;
    while (retryCount < context.MaxRetries)
    {
        try
        {
            using (var command = new SqlCommand(sqlCommand, dbConnection))
            {
                // ... Parameter setting and batch processing logic ...

                var startTime = DateTime.Now;

                using (var reader = await command.ExecuteReaderAsync())
                {
                    // ... Data processing with pagination or chunking ...
                }

                context.Callback(reader);
                Logger.LogInfo("Database operation completed successfully: {0}", context.OperationId);
                return;
            }
        }
        catch (Exception ex)
        {
            Logger.LogError($"Error executing database operation: {ex.Message}\nStack trace: {ex.StackTrace}");

            if (context.RetryLogic(ex))
            {
                retryCount++;
                await Task.Delay(TimeSpan.FromMilliseconds(Math.Pow(2, retryCount) * context.BaseDelay));
            }
            else
            {
                throw; // Re-throw the exception after retries 
            }
        }
    }

