# core/synchronization.py

from threading import Thread
from queue import Queue

class EventSynchronizer:
    def __init__(self, calendar_services: list[CalendarService]):
        self.calendar_services = calendar_services
        self.event_queue = Queue()

    def synchronize(self):
        threads = []
        for service in self.calendar_services:
            thread = Thread(target=self._process_events, args=(service,))
            threads.append(thread)
            thread.start()

        for thread in threads:
            thread.join()

    def _process_events(self, service: CalendarService):
        while True:
            event = self.event_queue.get()
            if event['action'] == 'create':
                service.create_event(event['data'])
            elif event['action'] == 'update':
                service.update_event(event['id'], event['data'])
            elif event['action'] == 'delete':
                service.delete_event(event['id'])



