from typing import Callable, Dict, List
import asyncio
import aiohttp
import logging


class BaseJSONHandler:
    def __init__(self):
        self.logger = logging.getLogger(__name__)

    async def fetch_data(self, url: str) -> Dict:
        raise NotImplementedError()

    def process_data(self, data: Dict) -> List:
        raise NotImplementedError()


class RESTfulJSONHandler(BaseJSONHandler):
    async def fetch_data(self, url: str) -> Dict:
        async with aiohttp.ClientSession() as session:
            async with session.get(url) as response:
                if response.status == 200:
                    return await response.json()
                else:
                    raise ValueError(f"API request failed with status code: {response.status}")

    def process_data(self, data: Dict) -> List:
        # Process RESTful API JSON data
        return [item["name"] for item in data["items"]]


class GraphQLJSONHandler(BaseJSONHandler):
    async def fetch_data(self, url: str, query: str) -> Dict:
        # Implement GraphQL query execution and data fetching

    def process_data(self, data: Dict) -> List:
        # Process GraphQL JSON data
        return [item["name"] for item in data["data"]["items"]]


class DynamicJSONHandlerFactory:
    handlers = {}

    def register_handler(self, name: str, handler_class: Callable) -> None:
        self.handlers[name] = handler_class

    def create_handler(self, name: str) -> BaseJSONHandler:
        return self.handlers[name]()


# Example usage
factory = DynamicJSONHandlerFactory()
factory.register_handler("restful", RESTfulJSONHandler)
factory.register_handler("graphql", GraphQLJSONHandler)

handler = factory.create_handler("restful")
await handler.fetch_data("https://api.example.com/items")


