# LogManager.py

class LogManager:
    def __init__(self):
        self._log_sources = {}  
        self._output_destinations = {}
        self._config = { 
            "max_batch_size": 1000, 
            "compression_level": 9, 
            "retry_attempts": 3
        }

    def register_log_source(self, source_id, log_handler):
        self._log_sources[source_id] = log_handler

    def register_output_destination(self, destination_id, handler):
        self._output_destinations[destination_id] = handler

    def configure(self, config):
        self._config.update(config)

    def process_logs(self):
        for source_id in self._log_sources:
            while True:  # Continuously receive logs from each source
                try:
                    log_entries = self._log_sources[source_id].get_logs() 
                    if log_entries:
                        self.send_to_destinations(log_entries)
                except Exception as e:
                    print(f"Error processing logs from {source_id}: {e}")
                    # Implement retry logic here

    def send_to_destinations(self, log_entries):
        for destination_id in self._output_destinations:
            try:
                self._output_destinations[destination_id].send_logs(log_entries)
            except Exception as e:
                print(f"Error sending logs to {destination_id}: {e}")

# Example Usage
class SimpleLogSource:
    def __init__(self):
        self.log_entries = []

    def get_logs(self):
        if self.log_entries:
            logs = self.log_entries[:]  
            self.log_entries = []  
            return logs
        else:
            return None

class NullDestination:
    def send_logs(self, logs):
        # Do nothing with logs (for testing purposes)
        pass



# Create a LogManager instance and configure it
logger = LogManager()
logger.configure({"max_batch_size": 500})

# Register log sources and destinations
log_source = SimpleLogSource()
logger.register_log_source("service1", log_source)

