                                ICacheService cacheService, ILogger logger)
    {
        _identityProviderFactory = identityProviderFactory;
        _databaseManager = databaseManager;
        _cacheService = cacheService;
        _logger = logger;
    }

    public async Task<AuthenticationResult> AuthenticateAsync(string username, string password)
    {
        // 1. Cache check for existing token (optional)
        var cachedToken = _cacheService.GetCachedToken(username); 

        if (cachedToken != null)
        {
            return new AuthenticationResult { Token = cachedToken }; // Return from cache
        }

        // 2. Database query for user credentials 
        var user = await _databaseManager.GetUserAsync(username);

        if (user == null)
