            _logger.LogError("User not found: {Username}", username);
            return new AuthenticationResult { IsSuccessful = false, Error = "Invalid credentials" };
        }

        // 3. Password validation logic (hash comparison, etc.)

        // ... Authenticate using selected method (OAuth2, JWT)
        var identityProvider = _identityProviderFactory.GetProvider(user.AuthenticationType); 
        var authenticationResult = await identityProvider.AuthenticateAsync(username, password);

        if (authenticationResult.IsSuccessful)
        {
