import java.io.*;
import java.util.*;
import java.net.URL;
import javax.xml.bind.JAXBException;

public class FileStateLoader {

    private static final Logger logger = LoggerFactory.getLogger(FileStateLoader.class);
    private final Map<String, MoSTState> cache = new ConcurrentHashMap<>();
    private final RemoteMetadataService metadataService;

    public FileStateLoader(RemoteMetadataService metadataService) {
        this.metadataService = metadataService;
    }

    /**
     * Loads a MoSTState object from a serialized file. 
     *
     * @param filename The path to the serialized file containing the MoSTState object.
     * @return A MoSTState object if the file contains a valid serialized object of that type, or null otherwise.
     */
    public MoSTState loadMoSTStateFromFile(String filename) {
        logger.info("Loading MoSTState from {}", filename);

        // Check cache first
        if (cache.containsKey(filename)) {
            logger.debug("MoSTState loaded from cache: {}", filename);
            return cache.get(filename);
        }

        try {
            // Validate file structure and contents with remote metadata service
            MetadataResponse response = metadataService.validateFile(filename);

            if (!response.isValid()) {
                logger.error("Invalid MoSTState file: {} - {}", filename, response.getErrorMessage());
                return null;
            }

            // Deserialize MoSTState object from file
            try (FileInputStream fileInputStream = new FileInputStream(filename)) {
                MoSTState state = ObjectInputStreamUtil.deserialize(fileInputStream);
                cache.put(filename, state);
                logger.info("MoSTState loaded successfully: {}", filename);
                return state;

            } catch (IOException | ClassNotFoundException e) {
                logger.error("Failed to load MoSTState from {} - {}", filename, e.getMessage());
                return null;
            }
        } catch (RestClientException e) {
            logger.error("Error communicating with remote metadata service: {}", e.getMessage());
            // Handle network errors gracefully
        }

        return null;
    }
}



```


