class RateLimiter {
  constructor() {
    this.maxRequests = 10; // Example limit
    this.windowDuration = 60 * 1000; // 1 minute window
    this.requestCounter = 0;
    this.lastResetTime = Date.now();

  }

  checkAndProceed() {
    const currentTime = Date.now();

    if (currentTime - this.lastResetTime >= this.windowDuration) {
      this.requestCounter = 0;
      this.lastResetTime = currentTime;
    }

    if (this.requestCounter < this.maxRequests) {
      this.requestCounter++;
      return true; // Proceed with request
    } else {
      // Handle rate limit exceeded
      console.error("Rate limit exceeded, retry after:", this.windowDuration - (currentTime - this.lastResetTime));
      return false;
    }
  }
}



