// CombatSystem.cpp

#include "CombatSystem.h"

CombatSystem::CombatSystem() : 
    // Initialize member variables here
{}

void CombatSystem::queueAttack(int characterId, const std::string& attackName) {
    std::unique_lock<std::mutex> lock(attackMutex);
    // Calculate cooldown end time based on attack type and character abilities.

    AttackData data{characterId, attackName, cooldownEndTime};
    pendingAttacks.push(data);
    attackCV.notify_one(); 
}


void CombatSystem::processAttacks() {
    while (true) {
        std::unique_lock<std::mutex> lock(attackMutex);
        attackCV.wait(lock, [this]{ return !pendingAttacks.empty(); });

        AttackData attack = pendingAttacks.front();
        pendingAttacks.pop(); 
        lock.unlock();

        // Execute attack logic based on `attackName` and character abilities.
        logAttack(attack); // Log the attack to the external service.
    }
}



``` 




