class LogProcessor {
 public:
  LogProcessor() : 
    processingThread(std::bind(&LogProcessor::processLogs, this)) {
      processingThread.detach();
  }

 private:
  void processLogs() {
    while (true) {
      // Acquire lock to access shared log queue
      {
        std::lock_guard<std::mutex> lock(logQueueMutex);
        // Wait for new logs or a signal
        conditionVariable.wait(lock, [this] { return !logQueue.empty(); });

        // Process the next log entry
        auto logEntry = std::move(logQueue.front());
        logQueue.pop();

        // Perform necessary processing on logEntry
        std::cout << "Processing: " << logEntry << std::endl; 

      }
    }
  }

  void addLogEntry(const std::string& logEntry) {
    {
      std::lock_guard<std::mutex> lock(logQueueMutex);
      logQueue.push(logEntry);
      // Notify the processing thread that new logs are available
      conditionVariable.notify_one(); 
    }
  }

  std::thread processingThread;
  std::queue<std::string> logQueue;
  std::mutex logQueueMutex;
  std::condition_variable conditionVariable;
};


int main() {
  LogProcessor processor;

  // Simulate adding logs from different sources
  processor.addLogEntry("File Log Entry");
  processor.addLogEntry("Network Feed Entry");
  processor.addLogEntry("API Response Log");

  return 0;
}
