<?php
class UserDao extends DatabaseHelper {
    public function updatePassword(int $userId, string $newPassword) {

        $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT); // Hash the new password securely

        $sql = "UPDATE users SET password = :password WHERE id = :userId"; 
        $stmt = $this->databaseConnection->prepare($sql);
        $stmt->bindParam(':password', $hashedPassword);
        $stmt->bindParam(':userId', $userId);

        if ($stmt->execute()) {
            return true; // Password updated successfully
        } else {
            // Handle database error gracefully
            throw new Exception("Error updating password in database"); 
        }
    }
}
?>
