// C function to create a new state list from an FSA

int *create_state_list(int *states, int num_states, struct FSA *fsa, int last_state) {
  // Allocate memory for the new state list.
  int *state_list = (int *)malloc((num_states + 1) * sizeof(int));
  if (state_list == NULL) {
    return NULL; // Memory allocation failed.
  }

  // Copy states from the input array to the new list.
  for (int i = 0; i < num_states; ++i) {
    state_list[i] = states[i];
  }
  state_list[num_states] = last_state; // Add the last state.

  // Update the number of states.
  num_states++;
  return state_list;
}


```



