    for (int i = 0; i < 1024; i++) {
        if (cache[i] != NULL && strcmp(cache[i]->key, key) == 0) {
            pthread_mutex_unlock(&cache_mutex);
            return cache[i]->data;
        }
    }
    pthread_mutex_unlock(&cache_mutex);
    return NULL; // Resource not found in cache
}

// Simplified function to free cached resources
