// C++ Code (Conceptual Outline) 

#include <iostream>
#include <thread>
#include <queue>
#include <mutex>
#include <condition_variable>

class LogProcessor {
public:
    LogProcessor(int workerCount) : workers(workerCount) {}

    void AddLog(const std::string& logData) {
        std::lock_guard<std::mutex> lock(logQueueMutex);
        logQueue.push(logData);
        conditionVariable.notify_one();
    }

    void Start() {
        for (int i = 0; i < workers; ++i) {
            workers.emplace_back([this]() {
                while (true) {
                    std::unique_lock<std::mutex> lock(logQueueMutex);
                    conditionVariable.wait(lock, [this] { return !logQueue.empty(); });

                    std::string logData = logQueue.front();
                    logQueue.pop();
                    lock.unlock();

