  let counter = 0;
  const interval = setInterval(() => {
    if (counter < scripts.length) {
      loadScript(scripts[counter]);
      counter++;
    } else {
      clearInterval(interval);
      console.log('All scripts loaded');
    }
  }, 100); // Adjust the interval as needed
};

