int establish_database_connection(Context* ctx) {
  // Token and Connection Validation
  if (!ctx->auth_token || !ctx->connection.title || ctx->connection.status == 0) {
    ctx->error_callback("Invalid authentication token or connection status.");
    return -1; // Error
  }

  // Configuration Validation
  if (ctx->config.timeout_ms <= 0 || ctx->config.retry_limit < 0) {
    ctx->error_callback("Invalid configuration parameters: timeout and retry limit must be positive.");
    return -1; // Error
  }

  pthread_t thread_id;
  int result = pthread_create(&thread_id, NULL, connection_thread, ctx);
  if (result != 0) {
    ctx->error_callback("Failed to create database connection thread.");
    return -1; // Error
  }

  // ... (Thread synchronization and cleanup)

  return 0; // Success
}



