pub fn compile_with_hook(code: &str, config: &AdaptiveCompilerConfig) -> CompilationMetrics {
    let start_time = Instant::now();
    let mut process = Command::new("rustc")
        .args(&["-C", "warnings=all"]) // Add custom compilation flags here
        .stdin(Stdin::from_iter(code.lines().map(|line| line.to_string() + "\n")))
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .expect("Failed to spawn compilation process");

    let output = process
        .wait_with_output()
        .expect("Compilation failed");

    let duration = start_time.elapsed();

    // Log compilation metrics (example using log crate)
    info!("Compilation completed in {}ms", duration.as_millis());
    info!("Memory usage: {}", process.memory_usage()); // Access memory usage here 

    CompilationMetrics {
        duration,
        output: output.stdout,
        stderr: output.stderr,
    }
}

#[derive(Debug)]
struct CompilationMetrics {
    duration: Duration,
    output: String,
    stderr: String,
}



