// Function for making geolocation API calls with retries and rate limiting
function geoApiCall($ipAddress, $geoApiConfig) {
    $retries = 0;
    while ($retries < $geoApiConfig['retry_attempts']) {
        try {
            $response = $geoApiClient->get($geoApiConfig['base_url'], ['params' => ['ip' => $ipAddress]]);
            if ($response->getStatusCode() == 200) {
                return json_decode($response->getBody(), true); // Parse JSON response
            } else {
                errorLog("Geolocation API call failed: Status Code " . $response->getStatusCode());
                sleep($geoApiConfig['retry_delay']); // Wait before retrying
                $retries++;
            }
        } catch (Exception $e) {
            errorLog("Geolocation API call error: " . $e->getMessage());
            sleep($geoApiConfig['retry_delay']); // Wait before retrying
            $retries++;
        }
    }

    // All retries failed, return null or an error object
    return null;
}


