public class XmlParser
{
    public string GetFirstElementByName(string xmlDocument, string elementName)
    {
        // Use XPath to navigate the XML document
        XPathDocument doc = new XPathDocument(new StringReader(xmlDocument));

        // Select the first element matching the specified name
        XPathNavigator nav = doc.CreateNavigator();
        XPathExpression expr = nav.Compile($"//*[local-name() = '{elementName}']");

        // Get the first matching element
        XPathNodeIterator nodes = nav.Select(expr);
        if (nodes.MoveNext())
        {
            return nodes.Current.Value;
        }
        else
        {
            throw new Exception($"No element found with name '{elementName}'");
        }
    }
}
```

