['```java
import java.io.*;
import java.nio.file.Files;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class DeviceDiagnostic {

    private final String command;
    private final String deviceId;
    private final File temporaryFile;

    public DeviceDiagnostic(String command, String deviceId) {
        this.command = command;
        this.deviceId = deviceId;
        this.temporaryFile = new File(String.format("/tmp/%s_diagnostic", deviceId));
    }

    public void execute() {
        ExecutorService executor = Executors.newSingleThreadExecutor();
        executor.execute(() -> {
            try {
                Files.deleteIfExists(temporaryFile.toPath());
                Process process = Runtime.getRuntime().exec(command, null, temporaryFile);
                handleOutputAndError(process);
            } catch (IOException e) {
                System.err.println("Error executing diagnostic command for device " + deviceId + ": " + e.getMessage());
            } finally {
                executor.shutdown();
            }
        });
    }

    private void handleOutputAndError(Process process) throws IOException {
        new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println("Device " + deviceId + ": " + line);
                }
            } catch (IOException e) {
                System.err.println("Error reading output from device diagnostic command: " + e.getMessage());
            }
        }).start();

        new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.err.println("Device " + deviceId + ": " + line);
                }
            } catch (IOException e) {
                System.err.println("Error reading error stream from device diagnostic command: " + e.getMessage());
            }
        }).start();

    }
}


```



