// This code provides a structural outline and essential components. 

public class SecureDataModule
{
    private readonly HsmClient _hsmClient; // Uses an HSM for key management
    private readonly Pbkdf2KeyDerivationFunction _pbkdf2;
    private readonly AesGcmCipher _aesGcm;
    private readonly ConcurrentDictionary<string, byte[]> _cachedIv = new();

    // Constructor with dependency injection for testability
    public SecureDataModule(HsmClient hsmClient, Pbkdf2KeyDerivationFunction pbkdf2)
    {
        _hsmClient = hsmClient;
        _pbkdf2 = pbkdf2;
        _aesGcm = new AesGcmCipher(); //  AES-GCM implementation
    }

    public byte[] Encrypt(string password, string salt, byte[] data) 
    {
        // Generate key using PBKDF2 with HSM for secure derivation
        byte[] key = _pbkdf2.DeriveKey(password, salt, hsmClient);

        // Generate fresh IV
        byte[] iv = Guid.NewGuid().ToByteArray(); // Replace with more robust IV generation

        _cachedIv[password + salt] = iv; 

        return _aesGcm.Encrypt(key, iv, data);
    }

    public byte[] Decrypt(string password, string salt, byte[] encryptedData)
    {
        // Retrieve cached IV using a unique identifier based on password and salt
        byte[] iv = _cachedIv[password + salt]; 

        // Generate key using PBKDF2 with HSM for secure derivation
        byte[] key = _pbkdf2.DeriveKey(password, salt, _hsmClient);

        return _aesGcm.Decrypt(key, iv, encryptedData);
    }

