def calculate_hash(file_path):
    with open(file_path, 'rb') as f:
        chunk_size = 4096
        data = f.read(chunk_size)
        md5_hasher = hashlib.md5()
        while data:
            md5_hasher.update(data)
            data = f.read(chunk_size)

    return md5_hasher.hexdigest()



def process_file(queue, hash_results):
    while True:
        file_path = queue.get()
        if file_path is None:
            break

        try:
            hash_value = calculate_hash(file_path) 
            hash_results[file_path] = hash_value
        except Exception as e:
            # ... Error handling, logging ...


def start_hashing(files):
    # ... Create multiprocessing pool based on available cores ...

    with multiprocessing.Pool(processes=4) as pool:  
        # Use the pool to process files concurrently
        pool.map(process_file, [(file,) for file in files]) 



if __name__ == "__main__":
    # ... Get file paths from input or configuration ...

    hash_results = {}
    queue = Queue()

    for file in files:
        queue.put(file)

    threads = []
    for i in range(4):  
        t = Thread(target=process_file, args=(queue, hash_results))
        threads.append(t)
        t.start()


