        Host.CreateDefaultBuilder(args)
            .ConfigureWebHostDefaults(webBuilder =>
            {
                webBuilder.UseStartup<Startup>();
            });
}

// Startup.cs
public class Startup
{
    public Startup(IConfiguration configuration)
    {
        Configuration = configuration;
    }

    public IConfiguration Configuration { get; }

    public void ConfigureServices(IServiceCollection services)
    {
        // Register authentication providers (OAuth2, JWT, API Keys)
        services.AddAuthentication()
            .AddOAuth2(...) // Implement OAuth2 provider configuration
            .AddJwtBearer(...) // Implement JWT bearer token configuration
            .AddApiKeyScheme(...); // Implement API key scheme

        // Configure external data sources and potential API integrations
        services.AddHttpClient<IExternalDataService, ExternalDataService>(client => 
        {
            client.BaseAddress = new Uri(Configuration["ExternalDataUrl"]);
        });

        // Register error handling middleware
        services.AddHealthChecks()
                .AddCheck("AuthenticationService", () => HealthCheckResult.Healthy());

        services.AddControllers(); // Add other required services
    }

    public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
    {
        if (env.IsDevelopment())
        {
            app.UseDeveloperExceptionPage();
        }

        // Apply middleware for authentication, logging, error handling, and caching
        app.UseAuthentication(); 
        app.UseAuthorization();
        app.UseRouting(); 
        app.UseEndpoints(endpoints =>
        {
            endpoints.MapControllers();
        });
    }
}

