    private readonly string _apiEndpoint; 
    private IHashStorageService _hashStorage;

    public FileHasher(string apiEndpoint)
    {
        _apiEndpoint = apiEndpoint;
    }

    public async Task HashFileAsync(string filePath)
    {
        using (var stream = File.OpenRead(filePath))
        {
            // Calculate MD5 hash in chunks
            var md5Hash = MD5.Create(); 
            byte[] hashBytes = null;  
            while (true)
            {
                byte[] chunk = await ReadChunkAsync(stream);
                if (chunk == null || chunk.Length == 0)
                    break;

                hashBytes = md5Hash.ComputeHash(chunk); 
            }

            // Store the hash in the external database
            await _hashStorage.StoreHashAsync(filePath, Convert.ToBase64String(hashBytes));
        }  
    }

