async fn process_files(repos: Vec<Arc<Repository>>, branches: &[String], paths: &[&str]) {
    let mut handles = vec![];
    for repo in repos.iter() {
        for branch in branches.iter() {
            for path in paths.iter() {
                let handle = tokio::spawn(async move {
                    match fetch_file(repo.clone(), branch, path).await {
                        FetchResult::Success(content) => {
                            // Process the fetched file content here
                            println!("Processed: {:?}", content);
                        }
                        FetchResult::Error(error) => {
                            println!("Error fetching {}: {}", path, error);
                        }
                    }
                });
                handles.push(handle);
            }
        }
    }

    // Wait for all file fetches to complete
    for handle in handles {
        let _ = handle.await;
    }
}

