public async Task<DatabaseOperationResult> ExecuteDatabaseOperation(DbConnection dbConnection, string sqlCommand, List<object> parameters, DatabaseOperationContext context)
{
    // Validation 
    if (dbConnection == null || !dbConnection.State.Equals(ConnectionState.Open))
    {
        LogError($"Database connection is invalid: {dbConnection}", context);
        return new DatabaseOperationResult { Success = false, Error = "Invalid database connection" };
    }

    if (string.IsNullOrEmpty(sqlCommand))
    {
        LogError($"SQL command is empty or null.", context);
        return new DatabaseOperationResult { Success = false, Error = "SQL command is required" };
    }

    if (parameters == null || parameters.Count == 0)
    {
        LogError($"Parameters list is empty.", context);
        return new DatabaseOperationResult { Success = false, Error = "Parameters are required" };
    }

    if (context.Callback == null)
    {
        LogError("Callback function is not defined.", context);
        return new DatabaseOperationResult { Success = false, Error = "Callback function is required" };
    }

    // Retry Logic with Exponential Backoff
    int retryCount = 0;
    while (retryCount < context.MaxRetries)
    {
        try
        {
            using (var command = new SqlCommand(sqlCommand, dbConnection))
            {
                // Parameter Handling & Database Execution 

            }
            context.Callback?.Invoke(new { Result = "Success", Data = "..." }); // Example Callback invocation
            return new DatabaseOperationResult { Success = true }; 
        }
        catch (Exception ex) when (context.RetryableExceptions.Contains(ex.GetType()))
        {
            // Logging & Backoff Implementation 

            retryCount++;
        }
    }

    LogError($"Database operation failed after {context.MaxRetries} retries.", context);
    return new DatabaseOperationResult { Success = false, Error = "Database operation failed" };  
}

```



