typedef struct {
    sem_t *pool;
    int size;
} SemaphorePoolManager;

SemaphorePoolManager* createSemaphorePool(int size) {
    SemaphorePoolManager* manager = malloc(sizeof(SemaphorePoolManager));
    manager->size = size;
    manager->pool = sem_open("semaphore_pool", O_CREAT | O_EXCL, 0644, size);
    return manager;
}

void destroySemaphorePool(SemaphorePoolManager* manager) {
    sem_close(manager->pool);
    sem_unlink("semaphore_pool");
    free(manager);
}

