@Path("/media")
public class MediaService {

    private CloudStorageClient cloudStorageClient;
    private DatabaseClient databaseClient;
    private CachingManager cachingManager;

    // Constructor for dependency injection
    public MediaService(CloudStorageClient cloudStorageClient, DatabaseClient databaseClient, CachingManager cachingManager) {
        this.cloudStorageClient = cloudStorageClient;
        this.databaseClient = databaseClient;
        this.cachingManager = cachingManager;
    }

    @POST
    @Consumes("multipart/form-data")
    public async Response uploadMedia(MultiPartFormData mediaData) throws IOException {
        // 1. Process Metadata: Extract relevant metadata from the uploaded file and request.
        String fileName = mediaData.getFilename();
        Map<String, String> metadata = extractMetadata(mediaData);

        // 2. Cloud Storage Upload: Use multipart upload strategy for large files.
        String cloudStorageUrl = cloudStorageClient.uploadMedia(mediaData.getInputStream(), fileName, metadata);

        // 3. Database Persistence: Store media information in the database.
        databaseClient.storeMedia(fileName, cloudStorageUrl, metadata);

        // 4. Caching: Cache metadata and thumbnail (if available) for faster retrieval.
        cachingManager.cacheMetadata(fileName, metadata);

        return Response.status(201).entity("Media uploaded successfully!").build();
    }

    @GET
    @Path("/{filename}")
    public async Response getMedia(@PathParam("filename") String filename) {
        // 1. Cache Retrieval: Attempt to retrieve media information from the cache.
        CachedMedia cachedMedia = cachingManager.getMedia(filename);

        if (cachedMedia != null) {
            return Response.ok(cachedMedia.getContent()).header("Content-Type", cachedMedia.getContentType()).build();
        } else {
            // 2. Database Query: Retrieve media information from the database.
            MediaEntity entity = databaseClient.getMedia(filename);

            // 3. Cloud Storage Retrieval: Download media from cloud storage using retrieved URL.
            InputStream mediaStream = cloudStorageClient.downloadMedia(entity.getCloudStorageUrl());

            // 4. Caching: Cache retrieved media for future requests.
            cachingManager.cacheMedia(filename, mediaStream, entity.getContentType());

            return Response.ok(mediaStream).header("Content-Type", entity.getContentType()).build();
        }
    }

    // ... (Other methods for deletion, tagging, etc.) 
}



