    private static Dictionary<Type, Func<object>> _factories = new Dictionary<Type, Func<object>>();

    public static void RegisterFactory<T>(Func<object> factory) where T : class
    {
        _factories[typeof(T)] = factory;
    }

    public static T CreateInstance<T>() where T : class
    {
        if (_factories.TryGetValue(typeof(T), out var factory))
        {
            return (T)factory();
        }
        throw new ArgumentException($"Factory for type {typeof(T)} not registered.");
    }
}

