// JavaScript function to copy bytes from a list of buffers

function copyBytes(dataChunks, byteCount) {
  const newBuffer = Buffer.allocUnsafe(byteCount); 
  let offset = 0;
  for (const chunk of dataChunks) {
    if (offset + chunk.length > byteCount) {
      chunk.copy(newBuffer, offset, 0, byteCount - offset);
      break; // Stop copying once the required bytes are copied
    } else {
      chunk.copy(newBuffer, offset);
      offset += chunk.length;
    }
  }
  return newBuffer;
}

```



