# DataFetcher Library Skeleton 

from concurrent import futures
import json
import logging
from typing import Callable, Dict, List

class Config:
    def __init__(self):
        self.sources = []  # Define data source configurations (REST API, DB, FS)

class DataSource:
    def __init__(self, config):
        self.config = config 

    def fetch_data(self, query: str) -> List[Dict]:
        raise NotImplementedError()

class DataFetcher:
    def __init__(self, config: Config):
        self.config = config
        self.executor = futures.ThreadPoolExecutor(max_workers=10) 
        self.data_sources = {source.name: DataSource(source.config) for source in self.config.sources}

    def fetch_data(self, query: str, source_name: str = None) -> List[Dict]:
        if not source_name:
            # Default to most frequently accessed source if no name specified
            raise NotImplementedError("Default source selection logic")

        source = self.data_sources[source_name]
        return self.executor.submit(source.fetch_data, query).result() 


# Example Configuration (placeholder)
config = Config()
config.sources = [
    {
        "name": "api1", 
        "type": "RESTAPI",  
        "url": "https://example-api.com/data",
        "headers": {"Authorization": "Bearer my_token"}
    },
    {
        "name": "db1",
        "type": "POSTGRESQL", 
        "host": "localhost",  
        "port": 5432, 
        "database": "my_database", 
        "user": "my_user",
        "password": "my_password"
    }
]



fetcher = DataFetcher(config)
results = fetcher.fetch_data("SELECT * FROM users WHERE active=TRUE", source_name="db1")

print(results) 
