// ... (Include headers for Kubernetes integration, logging, etc.)


typedef struct {
    sem_t* semaphore;
    int initial_value;
    int max_size;
} SemaphorePool;

SemaphorePool* createSemaphorePool(int initial_value, int max_size) {
    SemaphorePool* pool = malloc(sizeof(SemaphorePool));
    pool->semaphore = sem_open("my_semaphore_pool", O_CREAT | O_EXCL, 0644, initial_value);
    if (pool->semaphore == SEM_FAILED) {
        // Error handling: handle semaphore creation failure
        return NULL;
    }
    pool->initial_value = initial_value;
    pool->max_size = max_size;
    return pool;
}

void destroySemaphorePool(SemaphorePool* pool) {
    sem_close(pool->semaphore);
    sem_unlink("my_semaphore_pool"); 
    free(pool);
}

int acquireSemaphore(SemaphorePool* pool) {
    // Acquire semaphore and handle potential errors/retries
    return sem_wait(pool->semaphore);
}

void releaseSemaphore(SemaphorePool* pool) {
    sem_post(pool->semaphore); 
}



```



