        self.gateway_type = gateway_type  

    def process_transaction(self, amount, card_details):  
        # Implementation for processing transactions based on gateway_type
        pass 

class TransactionManager:
    def __init__(self):
        self.payment_gateways = {} 

    def register_gateway(self, gateway):
        self.payment_gateways[gateway.gateway_type] = gateway

    def process_transaction(self, amount, card_details, gateway_type="default"):
        gateway = self.payment_gateways.get(gateway_type) 
        if gateway:
            return gateway.process_transaction(amount, card_details)
        else:
            # Handle gateway not found error
            pass

class RetryStrategy:
    def __init__(self, initial_delay=1, max_retries=3):
        self.initial_delay = initial_delay
        self.max_retries = max_retries
        self.current_retry = 0

    def should_retry(self):
      if self.current_retry < self.max_retries:
          self.current_retry += 1
          return True
      else:
          return False

# ... Other modules for logging, monitoring, export/import, etc.


