public class DataProcessingPipeline {

    private final MessageBroker messageBroker;
    private final Database database;
    private final RestApiClient restApiClient;
    private final TransformationEngine transformationEngine;
    private final LoadBalancer loadBalancer;
    private final CachingStrategy cachingStrategy; 
    private final RetryMechanism retryMechanism;
    private final MonitoringSystem monitoringSystem;

    public DataProcessingPipeline(MessageBroker messageBroker, Database database, RestApiClient restApiClient,
                                 TransformationEngine transformationEngine, LoadBalancer loadBalancer,
                                 CachingStrategy cachingStrategy, RetryMechanism retryMechanism, 
                                 MonitoringSystem monitoringSystem) {
        this.messageBroker = messageBroker;
        this.database = database;
        this.restApiClient = restApiClient;
        this.transformationEngine = transformationEngine;
        this.loadBalancer = loadBalancer;
        this.cachingStrategy = cachingStrategy;
        this.retryMechanism = retryMechanism;
        this.monitoringSystem = monitoringSystem;
    }

    public Status processData(DataInput data) {
        // 1. Route data to appropriate workers based on type and load balancing
        Worker worker = loadBalancer.selectWorker(data);

        try {
            // 2. Transform data using the configured transformation rules
            DataOutput transformedData = transformationEngine.transform(data);

            // 3. Process transformed data based on its type (real-time or batch)
            if (data.isRealTime()) {
                // Send to message broker for real-time consumption
                messageBroker.send(transformedData);
            } else {
                // Store in database or process in batches
                database.save(transformedData); 
            }

        } catch (Exception e) {
            // Handle errors with retry mechanism and logging
            retryMechanism.handleRetry(e, data); 
            return Status.ERROR; 
        }

        monitoringSystem.trackPerformance(data);
        return Status.SUCCESS;  
    }

}


