sem_t semaphore;

void *processNFAPI_CRC_Indications(void *arg) {
  // Acquire semaphore for thread-safe access
  sem_wait(&semaphore);

  // Process a batch of indications 
  for (int i = 0; i < 1000; ++i) { // Adjust batch size as needed
    NFAPI_CRC_INDICATION_PDU_T indication;

    // ... Initialize RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG with random values

    // Randomly set CRCFLAG
    indication.CRCFLAG = rand() % 2;

    // ... Store indication in a data structure or queue safely

  }

  // Release semaphore to allow other threads
  sem_post(&semaphore);
  return NULL;
}


int main() {
  // Initialize semaphore
  sem_init(&semaphore, 0, 1); // Initial value 1 allows one thread at a time

  pthread_t threads[8]; // Adjust number of threads as needed
  for (int i = 0; i < 8; ++i) {
    pthread_create(&threads[i], NULL, processNFAPI_CRC_Indications, NULL);
  }

  // Wait for threads to complete
  for (int i = 0; i < 8; ++i) {
    pthread_join(threads[i], NULL);
  }

  sem_destroy(&semaphore); 
  return 0;
}

