  // ... Thread-safe logging initialization using shared memory
  // ... Error handling for network latency and timeouts

  if (creds->password->password == NULL || strlen(creds->password->password) == 0) {
    pthread_mutex_lock(&log_mutex); // Lock for thread safety
    log_error("Password is invalid or empty.");
    pthread_mutex_unlock(&log_mutex);
    return PASSWORD_ERROR;
  }

  if (creds->connection->title == NULL || strlen(creds->connection->title) == 0 || creds->connection->status < 0 || creds->connection->status > 100) {
    pthread_mutex_lock(&log_mutex); // Lock for thread safety
    log_error("Connection information is invalid.");
    pthread_mutex_unlock(&log_mutex);
    return CONNECTION_ERROR;
  }

  if (creds->callback->callback == NULL) {
    pthread_mutex_lock(&log_mutex); // Lock for thread safety
    log_error("Callback function is not set.");
    pthread_mutex_unlock(&log_mutex);
    creds->callback->enabled = 0;
    return CALLBACK_ERROR;
  }

  return SUCCESS;
}
