import io.netty.util.concurrent.DefaultEventExecutorGroup;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cloud.stream.annotation.EnableBinding;
import org.springframework.context.annotation.Bean;
import org.springframework.scheduling.concurrent.ThreadPoolTaskExecutor;

@SpringBootApplication
@EnableBinding(MultimediaMessageChannels.class)
public class MultimediaMicroserviceApplication {

    @Autowired
    private MultimediaStorageService storageService;

    @Bean
    public ThreadPoolTaskExecutor uploadExecutor() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setThreadNamePrefix("upload-");
        executor.setCorePoolSize(10);
        executor.setMaxPoolSize(50);
        executor.setQueueCapacity(200);
        return executor;
    }

    @Bean
    public DefaultEventExecutorGroup uploadEventExecutorGroup() {
        return new DefaultEventExecutorGroup(10);
    }

    public static void main(String[] args) {
        SpringApplication.run(MultimediaMicroserviceApplication.class, args);
    }
}
