ListEntry_t *list = NULL; 
size_t list_size = 0;
size_t max_size = 10000; // Initial maximum size

void add_pdu_to_list(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list_mutex);
    if (list_size >= max_size) {
        // Handle list overflow
        pthread_mutex_unlock(&list_mutex);
        return; 
    }

    ListEntry_t *entry = (ListEntry_t *)malloc(sizeof(ListEntry_t));
    entry->pdu = pdu; 

    list = (ListEntry_t *)realloc(list, (list_size + 1) * sizeof(ListEntry_t));
    list[list_size] = *entry;
    list_size++;

    pthread_mutex_unlock(&list_mutex);
}

