// libjsoncrypt.c

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h> // Include OpenSSL header
#include "crypto_algorithms.h" 


typedef struct {
    char *name;
    encrypt_func encrypt;
    decrypt_func decrypt;
} CryptoAlgorithm;

CryptoAlgorithm *registered_algorithms = NULL;
int num_registered_algorithms = 0;

void register_crypto_algorithm(encrypt_func encrypt, decrypt_func decrypt, const char *name) {
    CryptoAlgorithm *new_algorithm = malloc(sizeof(CryptoAlgorithm));
    new_algorithm->name = strdup(name);
    new_algorithm->encrypt = encrypt;
    new_algorithm->decrypt = decrypt;

