import threading

class ConnectionPool:
    def __init__(self, connection_factory, pool_size=10, priority_levels=None):
        self.connection_factory = connection_factory
        self.pool_size = pool_size
        self.priority_levels = priority_levels if priority_levels else ['LOW', 'MEDIUM', 'HIGH'] 
        self.available_connections = {}  # {priority: list of available connections}
        self.lock = threading.Lock()

    def acquire_connection(self, priority):
        with self.lock:
            if priority not in self.available_connections:
                self.available_connections[priority] = []
            if self.available_connections[priority]:
                return self.available_connections[priority].pop()  # Reuse existing connections
            else: 
                new_connection = self.connection_factory() 
                self.available_connections[priority].append(new_connection)
                return new_connection

    def release_connection(self, connection, priority):
        with self.lock:
            self.available_connections[priority].append(connection)  # Return to pool


# Example usage (replace with your actual database/API connections)
