class Logger {
 public:
  enum class LogLevel { DEBUG, INFO, WARNING, ERROR, CRITICAL };

  Logger(const std::string& logFilePath) : logFile_(logFilePath) {}

  void log(LogLevel level, const std::string& message) {
    // Acquire lock to ensure thread safety
    std::lock_guard<std::mutex> lock(mutex_);

    // Format the log entry
    // ... 

    // Add log entry to queue for asynchronous processing
    logQueue_.push(LogEntry{level, message});
    cv_.notify_one(); // Notify worker thread
  }

 private:
  struct LogEntry {
    LogLevel level;
    std::string message;
  };

  std::mutex mutex_;
  std::condition_variable cv_;
  std::queue<LogEntry> logQueue_;
  std::string logFile_;

  void workerThread() {
    while (true) {
      std::unique_lock<std::mutex> lock(mutex_);
      cv_.wait(lock, [this] { return !logQueue_.empty(); }); 

      // Process log entries from queue
      auto entry = logQueue_.front();
      logQueue_.pop();
      lock.unlock();

      // Write log entry to file, compress, rotate, etc.
      // ... 
    }
  }
};


