    @PutMapping("/resources/{id}")
    public ResponseEntity<Resource> updateResource(@PathVariable String id, 
                                                   @RequestBody Resource resource) {
        // Validate input data
        if (invalidData(resource)) {
            return ResponseEntity.badRequest().build();
        }

        circuitBreaker.checkCircuit(); // Implement circuit breaker logic

        try {
            Resource updatedResource = dataManager.updateResource(id, resource); 
            String md5Hash = calculateMD5Hash(updatedResource);
            updatedResource.setMd5Hash(md5Hash); 

            cacheManager.updateResourceCache(updatedResource);
            return ResponseEntity.ok(updatedResource);
        } catch (Exception e) {
            logger.error("Error updating resource: {}", e.getMessage());
            return ResponseEntity.internalServerError().build();
        }
    }

    @DeleteMapping("/resources/{id}")
    public ResponseEntity<Void> deleteResource(@PathVariable String id) {
        try {
            dataManager.deleteResource(id); 
            cacheManager.removeResourceFromCache(id);
            return ResponseEntity.noContent().build();
        } catch (Exception e) {
            logger.error("Error deleting resource: {}", e.getMessage());
            return ResponseEntity.internalServerError().build();
