#include <iostream>
#include <thread>
#include <queue>
#include <condition_variable>
#include <mutex>

// Placeholder for third-party tool interaction
class ImageConverter {
public:
  virtual ~ImageConverter() {}
  virtual bool convert(const std::string& input, const std::string& output) = 0;
};

class ThreadPool {
private:
  int numThreads;
  std::queue<std::function<void()>> tasks;
  std::condition_variable cv;
  std::mutex mutex;
  bool running;
public:
  ThreadPool(int numThreads) : numThreads(numThreads), running(true) {
    for (int i = 0; i < numThreads; ++i) {
      std::thread worker([this](){
        while (running) {
          std::function<void()> task;
          {
            std::unique_lock<std::mutex> lock(mutex);
            cv.wait(lock, [this]{ return !tasks.empty(); });
            task = std::move(tasks.front());
            tasks.pop();
          }
          task();
        }
      });
      worker.detach();
    }
  }
  ~ThreadPool() {
    running = false;
    cv.notify_all();
  }
  void addTask(std::function<void()> task) {
    {
      std::lock_guard<std::mutex> lock(mutex);
      tasks.push(task);
    }
    cv.notify_one();
  }
};

class ImageConversionService {
private:
  ImageConverter* converter;
  ThreadPool* threadPool;
public:
  ImageConversionService(ImageConverter* converter, ThreadPool* threadPool) : 
      converter(converter), threadPool(threadPool) {}

