use tokio::io::{AsyncWriteExt, AsyncReadExt};
use std::sync::mpsc;

async fn process_log(log_entry: String) {
    println!("Processing log entry: {}", log_entry); 
    // Your logic to handle the log entry here
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let (sender, receiver) = mpsc::channel(1024);

    // Start background flusher
    tokio::spawn(async move {
        loop {
            if let Ok(log_entry) = receiver.recv().await {
                process_log(log_entry).await; 
            }
        }
    });

    // Simulate receiving log entries
    for _ in 0..100 {
        let log_entry = format!("Log entry {}", rand::random::<u32>());
        sender.send(log_entry).await?;
    }

    Ok(())
}
```




**Explanation:**


* **Asynchronous Processing:** The `process_log` function handles individual log entries asynchronously using `tokio::main`. This allows for efficient processing of high volumes of logs without blocking the main thread.
