// C++ code for the Semaphore Pool Manager

#include <iostream>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <atomic>
#include <vector>
#include <map>
#include <queue>

class DistributedSemaphorePool {
public:
    // Constructor to initialize the semaphore pool
    DistributedSemaphorePool(size_t initialSize, size_t maxPoolSize) : 
        m_initialSize(initialSize), m_maxPoolSize(maxPoolSize), m_semaphoreCount(0) {}

    // Acquire a semaphore from the pool
    bool acquire() {
        std::lock_guard<std::mutex> lock(m_mutex);
        while (m_semaphoreCount == 0) {
            m_cv.wait(lock);
        }
        --m_semaphoreCount;
        return true;
    }

    // Release a semaphore back to the pool
    void release() {
        std::lock_guard<std::mutex> lock(m_mutex);
        ++m_semaphoreCount;
        m_cv.notify_one();
    }

private:
    size_t m_initialSize;
    size_t m_maxPoolSize;
    std::atomic<size_t> m_semaphoreCount;
    std::mutex m_mutex;
    std::condition_variable m_cv;
};



