    // Initialize and run file processing pipeline
    repository::fetch_files(&cli.repository, &cli.input_dir)
        .and_then(|files| parser::parse_files(files))
        .and_then(|parsed_code| llvm::generate_ir(parsed_code, &cli.output_dir))
