use tracing::{info, error};
use tokio::sync::mpsc;
use reqwest::Client;

async fn monitor_build_process(build_id: u64) {
    let (tx, rx) = mpsc::channel::<BuildMetrics>(1024);
    let client = Client::new();

    tokio::spawn(async move {
        loop {
            let metrics = collect_build_metrics(&client, build_id).await;
            if let Err(e) = tx.send(metrics).await {
                error!("Failed to send metrics: {:?}", e);
            }
            tokio::time::sleep(tokio::time::Duration::from_millis(50)).await;
        }
    });

    // Process incoming metrics from the worker
    while let Some(metrics) = rx.recv().await {
        process_build_metrics(metrics);
    }
}


