public class GameConfigManager
{
    private Dictionary<string, object> configCache = new Dictionary<string, object>();
    private ILogger logger;
    private XmlSchemaSet schemaSet; 

    // Constructor to initialize the logger and schemas.
    public GameConfigManager(ILogger logger, XmlSchemaSet schemaSet)
    {
        this.logger = logger;
        this.schemaSet = schemaSet;
    }

    // Load configuration from an XML file.
    public void LoadConfigFromFile(string filePath)
    {
        try 
        {
            // Read the XML file content.
            XDocument doc = XDocument.Load(filePath);
            // Validate the XML against the defined schema.
            doc.Validate(schemaSet, (sender, args) => {
                logger.LogError($"Invalid config file: {args.Message}");
                throw new Exception("XML validation failed."); 
            });

            // Populate the cache with the configuration data.
            foreach (XElement element in doc.Root.Elements())
            {
                configCache[element.Name.LocalName] = element.Value; 
            }
        }
        catch (Exception ex)
        {
            logger.LogError($"Error loading config file {filePath}: {ex.Message}");
        }
    }

    // Get a configuration value.
    public string GetConfigValue(string key)
    {
        if (configCache.TryGetValue(key, out object value)) 
        {
            return value.ToString();
        }
        else 
        {
            logger.LogWarning($"Configuration key '{key}' not found.");
            return null; // Or throw an exception depending on your needs.
        }
    }

    // Command-line interface integration (placeholder).
