    public LibraryManager(string libraryPath, string libraryChecksumUrl, string libraryDownloadUrl)
    {
        _libraryPath = libraryPath;
        _libraryChecksumUrl = libraryChecksumUrl;
        _libraryDownloadUrl = libraryDownloadUrl;
    }

    public int LoadLibrary() 
    {
        for (int retryCount = 0; retryCount < _maxRetries; retryCount++)
        {
            try 
            {
                // Checksum Verification
                string checksum = GetChecksum(_libraryPath);
                string expectedChecksum = GetChecksumFromDatabase(_libraryChecksumUrl);

                if (checksum == expectedChecksum)
                {
                    // Library is valid, load it
                    Assembly libraryAssembly = Assembly.LoadFile(_libraryPath);
                    // ... (Use loaded library here)

                    return 0; // Success
                }
                else
                {
                    // Library is corrupted, download a new copy
                    if (!DownloadLibrary(_libraryDownloadUrl))
                    {
                        throw new Exception("Failed to download library");
                    }
                }
            }
            catch (Exception ex) 
            {
                Logger.LogError($"Error loading library: {ex.Message}");
                // Handle exception, log details, and retry
                await Task.Delay(CalculateRetryDelay(retryCount));
            }
        }

        return -1; // Failed to load after retries
