import java.util.concurrent.TimeUnit;

public class DynamicService {

    private static boolean running = false;

    public static void main(String[] args) {
        while (true) {
            try {
                System.out.println("Service starting...");
                running = true;
                // Simulate service functionality here
                TimeUnit.SECONDS.sleep(5); // Keep running for 5 seconds

                System.out.println("Service stopping...");
                running = false;
                // Log stop message to messaging system
                System.out.println("Log message sent: Service stopped.");
            } catch (InterruptedException e) {
                System.err.println("Interrupted: " + e.getMessage());
            } finally {
                if (!running) {
                    try {
                        TimeUnit.SECONDS.sleep(5); // Random restart delay
                    } catch (InterruptedException ex) {
                        System.err.println("Restart interrupted: " + ex.getMessage());
                    }
                }
            }
        }
    }
}

```



