public class MoSTStateLoader {

    public static Object loadStateFromFile(String filePath) throws IOException {
        try (FileInputStream fileInputStream = new FileInputStream(filePath)) {
            ObjectInputStream objectInputStream = new ObjectInputStream(fileInputStream);
            try {
                Object loadedObject = objectInputStream.readObject();
                if (loadedObject instanceof MoSTState) {
                    return loadedObject;
                } else {
                    log.warn("Loaded object is not of type MoSTState: {}", loadedObject.getClass().getName());
                    return null;
                }
            } catch (ClassNotFoundException e) {
                log.error("Failed to find class for deserialization.", e);
                throw new IOException("Invalid state file format.", e);
            }
        } catch (IOException e) {
            log.error("Error reading state file: {}", filePath, e);
            throw e;
        }
    }
}
```



