// Secure Configuration File Update Function
async function updateConfigFile(configData) {
  const configFilePath = './config.json';
  let currentConfig = JSON.parse(fs.readFileSync(configFilePath, 'utf8'));
  for (const key in configData) {
    currentConfig[key] = configData[key];
  }
  // Encrypt Timestamp
  const timestamp = new Date().toISOString();
  const encryptedTimestamp = crypto.createHash('sha256').update(timestamp).digest('hex');

  currentConfig['__timestamp'] = encryptedTimestamp; // Append encrypted timestamp to config

  fs.writeFileSync(configFilePath, JSON.stringify(currentConfig));
}

