import java.io.*;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class MoSTStateService {

    private static final Logger logger = LoggerFactory.getLogger(MoSTStateService.class);
    private final ExternalDataStorageService storageService;
    private final int maxRetryAttempts = 3;
    private final ConcurrentHashMap<String, MoSTState> cache = new ConcurrentHashMap<>();

    public MoSTStateService(ExternalDataStorageService storageService) {
        this.storageService = storageService;
    }

    public MoSTState deserializeMoSTState(String key) {
        for (int i = 0; i < maxRetryAttempts; i++) {
            try (InputStream inputStream = storageService.retrieveData(key)) {
                ObjectInputStream objectInputStream = new ObjectInputStream(inputStream);
                MoSTState state = (MoSTState) objectInputStream.readObject();
                cache.putIfAbsent(key, state);
                return state;
            } catch (ClassNotFoundException | IOException e) {
                logger.error("Error deserializing MoSTState for key '{}' - Attempt {}/{}", key, i + 1, maxRetryAttempts, e);
            }
        }
        throw new RuntimeException("Failed to deserialize MoSTState after " + maxRetryAttempts + " attempts.");
    }
}
