const express = require('express');
const axios = require('axios');
const mongoose = require('mongoose');
const cron = require('node-cron');

const app = express();

// Configuration
const config = {
  apis: [
    { url: 'https://api.example1.com/data', batchSize: 100 },
    { url: 'https://api.example2.com/data', batchSize: 500 },
  ],
  db: 'mongodb://localhost:27017/streaming_data',
};

// Data model
const DataPoint = mongoose.model('DataPoint', {
  source: String,
  timestamp: Number,
  value: JSON,
});

// Ingestion function
async function ingestData(api) {
  try {
    const response = await axios.get(api.url);
    const data = response.data;

    for (let i = 0; i < data.length; i += api.batchSize) {
      const batch = data.slice(i, i + api.batchSize);
      await DataPoint.insertMany(batch);
    }
  } catch (error) {
    console.error(`Error ingesting data from ${api.url}:`, error);
  }
}

// Cron job to periodically ingest data
cron.schedule('*/5 * * * *', async () => {
  for (const api of config.apis) {
    await ingestData(api);
  }
});

// Start the server
app.listen(3000, () => console.log('Microservice listening on port 3000'));
