import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DiagnosticModule {

    private final ExecutorService executor = Executors.newSingleThreadExecutor(); 

    public void executeCommand(String deviceId, String command) {
        // ... logic to build the full command string based on deviceId and command type

        Path tempFile = Path.of("temp_" + deviceId);
        try {
            Files.deleteIfExists(tempFile); 
        } catch (IOException e) {
            System.err.println("Error deleting temporary file: " + e.getMessage());
        }

        executor.submit(() -> {
            try {
                Process process = Runtime.getRuntime().exec(command, null, tempFile.toFile());
                BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println("Device " + deviceId + ": " + line); 
                    // ... process output data
                }
                reader.close();

                BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));
                while ((line = errorReader.readLine()) != null) {
                    System.err.println("Device " + deviceId + ": Error: " + line); 
                    // ... handle error data
                }
                errorReader.close();

            } catch (IOException e) {
                System.err.println("Error executing command on device " + deviceId + ": " + e.getMessage());
                // ... implement error handling and retry logic
            }
        }); 
    }

    public void shutdown() {
        executor.shutdown();
    }
}




```



