    [HttpPost("/decrypt")]
    public async Task<IActionResult> DecryptMessage([FromBody] string base64EncryptedMessage)
    {
        try
        {
            // 1. Decode Base64 message
            byte[] encryptedBytes = Convert.FromBase64String(base64EncryptedMessage);

            // 2. Decrypt using TripleDES with key and IV (from configuration or secure storage)
            using (TripleDESCryptoServiceProvider des = new TripleDESCryptoServiceProvider())
            {
                des.Key = Encoding.UTF8.GetBytes("YOUR_SECRET_KEY"); // Replace with actual key
                des.IV = Encoding.UTF8.GetBytes("YOUR_INITIALIZATION_VECTOR"); // Replace with actual IV

                using (ICryptoTransform decryptor = des.CreateDecryptor())
                {
                    byte[] decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

                    // 3. Process decrypted data (e.g., store in database, send to queue)
                    await EnqueueDecryptedMessage(decryptedBytes); // Example: Send message to queue

                    return Ok("Decryption successful");
                }
            }
        }
        catch (Exception ex)
        {
            Logger.Error(ex, "Error during message decryption");
            return StatusCode(500, "Internal server error");
        }
    }

