#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define semaphore structure
typedef struct {
    int value;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} Semaphore;

// ... (Functions for semaphore creation, initialization, deletion, etc.)

// Example function for acquiring a semaphore
void acquireSemaphore(Semaphore *sem) {
    pthread_mutex_lock(&sem->mutex);
    while (sem->value == 0) {
        pthread_cond_wait(&sem->cond, &sem->mutex);
    }
    sem->value--;
    pthread_mutex_unlock(&sem->mutex);
}

// Example function for releasing a semaphore
void releaseSemaphore(Semaphore *sem) {
    pthread_mutex_lock(&sem->mutex);
    sem->value++;
    pthread_cond_signal(&sem->cond);
    pthread_mutex_unlock(&sem->mutex);
}

``` 


