  std::vector<std::thread> workerThreads(4); // Example: 4 worker threads for processing

  for (auto& thread : workerThreads) {
    thread = std::thread(processEvents);
  }

  // Keep the main thread alive to prevent program termination
  for (auto& thread : workerThreads) {
    thread.join();
  }
  eventGenerator.join();
